use std::io::Write;
use std::path::PathBuf;
use std::process::{Command,Output,Stdio};
use std::sync::atomic::{AtomicU64,Ordering};
const BIN:&str=env!("CARGO_BIN_EXE_lfz");
static NEXT:AtomicU64=AtomicU64::new(0);
struct Work(PathBuf);
impl Work {
 fn new()->Self {let p=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("Temp/T16-B-tooling/tests").join(format!("{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir_all(&p).unwrap();Self(p)}
 fn file(&self,name:&str,body:&str)->String {let p=self.0.join(name);std::fs::write(&p,format!("#42\n{body}")).unwrap();p.to_str().unwrap().into()}
 fn run(&self,args:&[&str],stdin:&[u8])->Output {let mut c=Command::new(BIN).args(args).current_dir(&self.0).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();if let Some(mut p)=c.stdin.take(){let _=p.write_all(stdin);}let end=std::time::Instant::now()+std::time::Duration::from_secs(10);while c.try_wait().unwrap().is_none(){if std::time::Instant::now()>=end{let _=c.kill();let _=c.wait();panic!("模块check进程超时");}std::thread::sleep(std::time::Duration::from_millis(5));}c.wait_with_output().unwrap()}
}
fn pass(r:Output){assert_eq!(r.status.code(),Some(0),"{:?}",r);assert_eq!(r.stdout,b"{\"ok\":true,\"mode\":\"check\",\"executed\":false}\n");assert!(r.stderr.is_empty());}
fn error(r:Output,class:&str)->String {assert_eq!(r.status.code(),Some(2),"{:?}",r);assert!(r.stderr.is_empty());let s=String::from_utf8(r.stdout).unwrap();assert!(s.contains(&format!("\"error\":\"{class}\"")),"{s}");assert!(s.contains("\"executed\":false"));s}
#[test] fn graph_diamond_check_never_initializes_dependencies(){let w=Work::new();w.file("shared.lfz","let n=1\nexport n\nwriteFile(\"sentinel.txt\",\"bad\")\nwhile true {}\n");w.file("a.lfz","import s from \"./shared.lfz\"\nexport s\n");w.file("b.lfz","import s from \"./shared.lfz\"\nexport s\n");let root=w.file("root.lfz","import a from \"./a.lfz\"\nimport b from \"./b.lfz\"\nprint(1)\n");pass(w.run(&["check",&root,"--json"],b""));assert!(!w.0.join("sentinel.txt").exists());}
#[test] fn code_and_stdin_use_captured_cwd(){let w=Work::new();w.file("dep.lfz","let x=1\nexport x\n");let s="import d from \"./dep.lfz\"\nexport d\n";pass(w.run(&["check","-e",s,"--json"],b""));pass(w.run(&["check","-","--json"],s.as_bytes()));}
#[test] fn dependency_syntax_uses_own_path_and_source(){let w=Work::new();let dep=w.file("dep.lfz","let broken =\n");let root=w.file("root.lfz","import d from \"./dep.lfz\"\nlet root_marker=1\n");let s=error(w.run(&["check",&root,"--json"],b""),"SyntaxError");let canonical=std::fs::canonicalize(dep).unwrap().to_str().unwrap().replace('\\',"\\\\");assert!(s.contains(&format!("\"file\":\"{canonical}\"")),"{s}");let human=w.run(&["check",&root],b"");let text=String::from_utf8(human.stderr).unwrap();assert!(text.contains("let broken ="));assert!(!text.contains("import d from"));assert!(!text.contains("root_marker"));}
#[test] fn missing_and_invalid_dependency_diagnostics_are_not_root_text(){let w=Work::new();let root=w.file("root.lfz","import d from \"./absent.lfz\"\n");let s=error(w.run(&["check",&root,"--json"],b""),"IOError");assert!(s.contains("无法读取模块"));assert!(s.contains("\"line\":null,\"col\":null,\"traceback\":[]"));std::fs::write(w.0.join("absent.lfz"),[0xff]).unwrap();let s=error(w.run(&["check",&root,"--json"],b""),"SyntaxError");assert!(s.contains("absent.lfz"));}
#[test] fn exports_conflicts_cycles_and_legacy_identifiers(){let w=Work::new();for (body,message) in [("export missing\n","导出名没有顶层声明"),("let x=1\nexport x,x\n","重复导出"),("import d from \"./a.lfz\"\nlet d=1\n","模块导入名冲突")]{w.file("a.lfz","let x=1\n");let p=w.file("root.lfz",body);let s=error(w.run(&["check",&p,"--json"],b""),"SyntaxError");assert!(s.contains(message),"{s}");}w.file("a.lfz","import d from \"./root.lfz\"\n");let p=w.file("root.lfz","import d from \"./a.lfz\"\n");assert!(error(w.run(&["check",&p,"--json"],b""),"SyntaxError").contains("模块循环依赖"));pass(w.run(&["check","-e","let export=1\nexport = 2\nexport + 1","--json"],b""));}
#[test] fn legacy_large_root_has_no_graph_budget(){let w=Work::new();let padding=format!("//{}\n","x".repeat(2*1024*1024));let p=w.file("large.lfz",&(padding.clone()+"print(1)\n"));pass(w.run(&["check",&p,"--json"],b""));w.file("large.lfz",&(padding+"let x=1\nexport x\n"));assert!(error(w.run(&["check",&p,"--json"],b""),"SyntaxError").contains("单文件字节"));}
#[test] fn run_rejects_module_before_any_side_effect(){let w=Work::new();let p=w.file("root.lfz","writeFile(\"sentinel.txt\",\"bad\")\nprint(1)\nlet x=1\nexport x\n");let r=w.run(&["run",&p],b"");assert_eq!(r.status.code(),Some(2));assert!(r.stdout.is_empty());assert!(String::from_utf8_lossy(&r.stderr).contains("模块执行尚未启用"));assert!(!w.0.join("sentinel.txt").exists());}
